p.STATUS_CD = 'NORMAL'


    AND p.CATEGORY_ID IN (
        SELECT CATEGORY_ID FROM TB_PRODUCT_CATEGORY
        START WITH CATEGORY_ID = #{categoryId}
        CONNECT BY PRIOR CATEGORY_ID = PARENT_ID
    )


    AND (UPPER(p.PRODUCT_NAME) LIKE '%' || UPPER(#{keyword}) || '%'
         OR UPPER(p.BRAND_NAME) LIKE '%' || UPPER(#{keyword}) || '%')



    AND TO_NUMBER(p.SALE_PRICE) >= #{minPrice}


    AND TO_NUMBER(p.SALE_PRICE) <= #{maxPrice}


    AND p.BIZ_NO = #{bizNo}

mapper.select:
SELECT p.PRODUCT_ID, #{optionId, jdbcType=NUMERIC} AS OPTION_ID, p.PRODUCT_NAME, p.BRAND_NAME, p.BIZ_NO, b.BIZ_NAME, f.FILE_URL AS THUMBNAIL_URL, o.OPTION_COLOR, o.OPTION_SIZE, TO_NUMBER(p.SALE_PRICE) + NVL(o.ADD_PRICE, 0) AS PRICE, NVL(o.STOCK_QTY, (SELECT NVL(SUM(STOCK_QTY),0) FROM TB_PRODUCT_OPTION WHERE PRODUCT_ID = p.PRODUCT_ID)) AS STOCK_QTY
FROM TB_PRODUCT p JOIN TB_BUSINESS b ON b.BIZ_NO = p.BIZ_NO LEFT JOIN TB_PRODUCT_OPTION o
ON o.PRODUCT_ID = p.PRODUCT_ID AND o.OPTION_ID = #{optionId, jdbcType=NUMERIC} LEFT JOIN ( SELECT REF_ID, FILE_URL, ROW_NUMBER() OVER ( PARTITION BY REF_ID ORDER BY FILE_ID ) AS RN FROM TB_FILE WHERE REF_TYPE = 'PRODUCT' ) f ON f.REF_ID = p.PRODUCT_ID AND f.RN = 1 WHERE p.PRODUCT_ID = #{productId}

SELECT CART_ITEM_ID FROM TB_CART_ITEM
WHERE CART_ID = #{cartId} AND PRODUCT_ID = #{productId}

    AND OPTION_ID = #{optionId, jdbcType=NUMERIC}


    AND OPTION_ID IS NULL

AND ROWNUM = 1

