UPDATE TB_MEMBER
   SET POINT_BALANCE = NVL(POINT_BALANCE, 0) - #{pointUsed}
 WHERE MEMBER_NO = #{memberNo}
   AND NVL(POINT_BALANCE, 0) >= #{pointUsed}

UPDATE TB_PRODUCT_OPTION
SET STOCK_QTY = GREATEST(0, STOCK_QTY - #{qty})
WHERE OPTION_ID = #{optionId}

